            dem[depot_id] = 0
        for k in coords:
            if k not in dem:
                dem[k] = 0
        customers = [i for i in coords if i != depot_id]
        customers.sort()
        return cap, depot_id, coords, dem, dm, customers

    cap, depot, coords, dem, dm, customers = parse(instance)
    if not customers:
        return []

    cache = {}
    def dist(a, b):
        if a == b:
            return 0.0
        key = (a, b)
        v = cache.get(key)
        if v is not None:
            return v
        if dm is not None:
            v = dm[a][b]
        else:
            ax, ay = coords[a]
            bx, by = coords[b]
            dx = ax - bx
            dy = ay - by
            v = (dx * dx + dy * dy) ** 0.5
        cache[key] = v
        cache[(b, a)] = v
        return v

    def load(r):
        s = 0
        for x in r:
            s += dem.get(x, 0)
        return s

    def rcost(r):
        if not r:
            return 0.0
        c = dist(depot, r[0])
        for i in range(len(r) - 1):
            c += dist(r[i], r[i + 1])
        return c + dist(r[-1], depot)

    routes = [[x] for x in customers]
    pos = {x: i for i, x in enumerate(customers)}
    sav = []
    for i in customers:
        di = dist(depot, i)
        for j in customers:
            if j > i:
                sav.append((-(di + dist(depot, j) - dist(i, j)), i, j))
    sav.sort()

    changed = True
    while changed:
        changed = False
        for _, i, j in sav:
            ri = pos.get(i)
            rj = pos.get(j)
            if ri is None or rj is None or ri == rj:
                continue
            A = routes[ri]
            B = routes[rj]
            if not A or not B or load(A) + load(B) > cap:
                continue
            a0, a1 = A[0], A[-1]
            b0, b1 = B[0], B[-1]
            merged = None
            if a1 == i and b0 == j:
                merged = A + B
            elif a0 == i and b1 == j:
                merged = A[::-1] + B[::-1]
            elif a1 == i and b1 == j:
                merged = A + B[::-1]
            elif a0 == i and b0 == j:
                merged = A[::-1] + B
            if merged is not None:
                routes[ri] = merged
                routes[rj] = []
                for x in merged:
                    pos[x] = ri
                changed = True
    routes = [r for r in routes if r]

    def two_opt_best(r):
        n = len(r)
        best = r
        bestc = rcost(r)
        imp = False
        for i in range(n - 2):
            for k in range(i + 2, n):
                if i == 0 and k == n - 1:
                    continue
                cnd = r[:i + 1] + r[i + 1:k + 1][::-1] + r[k + 1:]
                c = rcost(cnd)
                if c + 1e-12 < bestc:
                    best, bestc, imp = cnd, c, True
        return best, imp

    for _ in range(2):
        routes = [two_opt_best(r)[0] for r in routes]
        best_delta = 0.0
        best = None
        m = len(routes)
        for a in range(m):
            ra = routes[a]
            if not ra:
                continue
            ca = rcost(ra)
            la = load(ra)
            for ia, x in enumerate(ra):
                ra2 = ra[:ia] + ra[ia + 1:]
                if not ra2:
                    continue
                ca2 = rcost(ra2)
                dx = dem.get(x, 0)
                for b in range(m):
                    if a == b:
                        continue
                    rb = routes[b]
                    if load(rb) + dx > cap:
                        continue
                    cb = rcost(rb)
                    for ib in range(len(rb) + 1):
                        rb2 = rb[:ib] + [x] + rb[ib:]
                        dlt = (ca2 + rcost(rb2)) - (ca + cb)
                        if dlt < best_delta - 1e-12:
                            best_delta = dlt
                            best = (a, b, ia, ib, rb2)
        if best is None:
            break
        a, b, ia, ib, rb2 = best
        x = routes[a][ia]
        routes[a] = routes[a][:ia] + routes[a][ia + 1:]
        routes[b] = rb2
        if not routes[a]:
            routes.pop(a)
        routes = [r for r in routes if r]
    return routes
